def scan_targets(targets,check):
    if not callable(check):raise ValueError('callback')
    source=iter(targets);stop=object();result={'total':0,'passed':0,'failures':[],'complete':False,'iteration_error':None}
    while True:
        try:current=next(source,stop)
        except Exception as error:
            result['iteration_error']=type(error).__name__;return result
        if current is stop:result['complete']=True;return result
        index=result['total'];result['total']+=1
        try:accepted=check(current)
        except Exception as error:result['failures'].append({'index':index,'error':type(error).__name__})
        else:
            if accepted:result['passed']+=1
            else:result['failures'].append({'index':index,'error':'check returned false'})
